<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'
import { api, dateTime } from './api'
import type { Module } from './types'

const props = defineProps<{ module: Module; recordId: string; canWrite: boolean; userId: string; manager: boolean }>()
const emit = defineEmits<{ changed: [] }>()
type Plan = { id: string; content: string; method: string; status: string; owner_name: string; estimated_at: string; converted: boolean }
type Comment = { id: string; user_id: string; user_name: string; content: string; created_at: string }
const plans = ref<Plan[]>([]), comments = ref<Record<string, Comment[]>>({}), commentDrafts = ref<Record<string, string>>({}), content = ref(''), method = ref('电话'), estimatedAt = ref(''), error = ref(''), busy = ref(false)
const labels: Record<string, string> = { prepared: '未开始', underway: '进行中', completed: '已完成', cancelled: '已取消' }
async function loadComments(planId: string) { comments.value[planId] = (await api<{items: Comment[]}>(`/followup-plans/${planId}/comments`)).items }
async function load() { try { plans.value = (await api<{items: Plan[]}>(`/records/${props.module.key}/${props.recordId}/followup-plans`)).items; comments.value = {}; await Promise.all(plans.value.map(plan => loadComments(plan.id))); error.value = '' } catch (e) { error.value = (e as Error).message } }
async function create() { if (busy.value) return; busy.value = true; try { await api(`/records/${props.module.key}/${props.recordId}/followup-plans`, 'POST', { content: content.value, method: method.value, estimated_at: new Date(estimatedAt.value).toISOString() }); content.value = ''; estimatedAt.value = ''; await load(); emit('changed') } catch (e) { error.value = (e as Error).message } finally { busy.value = false } }
async function status(plan: Plan, value: string) { try { await api(`/followup-plans/${plan.id}/status`, 'POST', { status: value }); await load(); emit('changed') } catch (e) { error.value = (e as Error).message } }
async function remove(plan: Plan) { if (!confirm('删除此跟进计划？')) return; try { await api(`/followup-plans/${plan.id}`, 'DELETE'); await load(); emit('changed') } catch (e) { error.value = (e as Error).message } }
async function addComment(plan: Plan) { const content = (commentDrafts.value[plan.id] || '').trim(); if (!content) return; try { await api(`/followup-plans/${plan.id}/comments`, 'POST', { content }); commentDrafts.value[plan.id] = ''; await loadComments(plan.id) } catch (e) { error.value = (e as Error).message } }
async function removeComment(plan: Plan, comment: Comment) { if (!confirm('删除此评论？')) return; try { await api(`/followup-plans/${plan.id}/comments/${comment.id}`, 'DELETE'); await loadComments(plan.id) } catch (e) { error.value = (e as Error).message } }
async function editComment(plan: Plan, comment: Comment) { const content = window.prompt('编辑评论', comment.content)?.trim(); if (!content || content === comment.content) return; try { await api(`/followup-plans/${plan.id}/comments/${comment.id}`, 'PUT', { content }); await loadComments(plan.id) } catch (e) { error.value = (e as Error).message } }
onMounted(load); watch(() => props.recordId, load)
</script>
<template><div class="plans"><form v-if="canWrite" class="followup-form" @submit.prevent="create"><h3>新增跟进计划</h3><textarea v-model="content" required maxlength="3000" placeholder="预计沟通内容" rows="3"/><div><select v-model="method"><option v-for="v in ['电话','微信','邮件','拜访','会议','其他']" :key="v">{{ v }}</option></select><input v-model="estimatedAt" required type="datetime-local"/><button class="button primary" :disabled="busy">创建计划</button></div></form><p v-if="error" class="error-banner">{{ error }}</p><div v-if="!plans.length" class="empty">暂无跟进计划</div><article v-for="plan in plans" :key="plan.id" class="followup-card"><header><b>{{ plan.owner_name }}</b><span class="badge blue">{{ labels[plan.status] }}</span><time>{{ dateTime(plan.estimated_at) }}</time></header><p>{{ plan.content }}</p><small>{{ plan.method }}</small><div v-if="canWrite && !plan.converted"><select v-if="!['completed','cancelled'].includes(plan.status)" :value="plan.status" @change="status(plan, ($event.target as HTMLSelectElement).value)"><option value="prepared">未开始</option><option value="underway">进行中</option><option value="completed">已完成</option><option value="cancelled">已取消</option></select><button class="text-button danger" @click="remove(plan)">删除</button></div><section class="plan-comments"><b>协作评论</b><div v-if="!(comments[plan.id] || []).length" class="muted">暂无评论</div><div v-for="comment in comments[plan.id] || []" :key="comment.id" class="plan-comment"><strong>{{ comment.user_name }}</strong><span>{{ comment.content }}</span><time>{{ dateTime(comment.created_at) }}</time><button v-if="comment.user_id === userId || manager" class="text-button" @click="editComment(plan, comment)">编辑</button><button v-if="comment.user_id === userId || manager" class="text-button danger" @click="removeComment(plan, comment)">删除</button></div><form v-if="canWrite" @submit.prevent="addComment(plan)"><textarea v-model="commentDrafts[plan.id]" required maxlength="2000" placeholder="添加协作评论" rows="2"/><button class="text-button">发表评论</button></form></section></article></div></template>
